"use client";

import React, { useEffect, useRef } from "react";
import {
  motion,
  useInView,
  useMotionValue,
  useSpring,
  useTransform,
} from "framer-motion";
import { cn } from "@/lib/utils";
import { SparklineChart } from "./sparkline-chart";

interface KPICardProps {
  title: string;
  value: number;
  prefix?: string;
  suffix?: string;
  change?: number;
  sparklineData?: number[];
  className?: string;
}

function AnimatedNumber({
  value,
  prefix = "",
  suffix = "",
}: {
  value: number;
  prefix?: string;
  suffix?: string;
}) {
  const ref = useRef<HTMLSpanElement>(null);
  const isInView = useInView(ref, { once: true, margin: "-40px" });
  const motionVal = useMotionValue(0);
  const spring = useSpring(motionVal, { stiffness: 80, damping: 20, mass: 1 });
  const display = useTransform(spring, (v: number) => {
    if (Number.isInteger(value)) return Math.round(v).toLocaleString();
    return v.toFixed(2);
  });

  useEffect(() => {
    if (isInView) motionVal.set(value);
  }, [isInView, value, motionVal]);

  return (
    <span ref={ref} className="inline-flex items-baseline gap-1">
      {prefix && (
        <span className="text-lg font-semibold text-zinc-500">{prefix}</span>
      )}
      <motion.span className="tabular-nums">{display}</motion.span>
      {suffix && (
        <span className="text-lg font-semibold text-zinc-500">{suffix}</span>
      )}
    </span>
  );
}

export function KPICard({
  title,
  value,
  prefix,
  suffix,
  change,
  sparklineData,
  className,
}: KPICardProps) {
  const isPositive = change !== undefined && change >= 0;
  const isNegative = change !== undefined && change < 0;

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5, ease: "easeOut" }}
      className={cn(
        "group relative overflow-hidden rounded-2xl border border-white/[0.08] bg-zinc-950/80 backdrop-blur-xl",
        className
      )}
    >
      {/* Top accent line */}
      <div className="h-[1px] bg-gradient-to-r from-transparent via-white/[0.06] to-transparent" />

      <div className="p-6">
        {/* Title row */}
        <div className="flex items-center justify-between">
          <p className="text-sm font-medium text-zinc-500">{title}</p>
          {change !== undefined && (
            <span
              className={cn(
                "inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-xs font-semibold",
                isPositive &&
                  "bg-emerald-500/10 text-emerald-400 ring-1 ring-emerald-500/20",
                isNegative &&
                  "bg-red-500/10 text-red-400 ring-1 ring-red-500/20"
              )}
            >
              {/* Arrow */}
              <svg
                width="10"
                height="10"
                viewBox="0 0 10 10"
                fill="none"
                className={cn(isNegative && "rotate-180")}
              >
                <path
                  d="M5 2L8 6H2L5 2Z"
                  fill="currentColor"
                />
              </svg>
              {Math.abs(change).toFixed(1)}%
            </span>
          )}
        </div>

        {/* Big number */}
        <div className="mt-3 text-3xl font-bold tracking-tight text-white">
          <AnimatedNumber value={value} prefix={prefix} suffix={suffix} />
        </div>

        {/* Sparkline */}
        {sparklineData && sparklineData.length >= 2 && (
          <div className="mt-4">
            <SparklineChart
              data={sparklineData}
              width={220}
              height={40}
              showArea
              animate
              color={isNegative ? "#f87171" : "#34d399"}
            />
          </div>
        )}
      </div>
    </motion.div>
  );
}

"use client";

import React, { useMemo, useId } from "react";
import { motion } from "framer-motion";
import { cn } from "@/lib/utils";

interface SparklineChartProps {
  data: number[];
  className?: string;
  color?: string;
  height?: number;
  width?: number;
  showArea?: boolean;
  animate?: boolean;
}

function buildSmoothPath(
  points: { x: number; y: number }[]
): string {
  if (points.length < 2) return "";
  const d: string[] = [`M ${points[0].x},${points[0].y}`];
  for (let i = 0; i < points.length - 1; i++) {
    const p0 = points[Math.max(i - 1, 0)];
    const p1 = points[i];
    const p2 = points[i + 1];
    const p3 = points[Math.min(i + 2, points.length - 1)];
    const tension = 0.3;
    const cp1x = p1.x + (p2.x - p0.x) * tension;
    const cp1y = p1.y + (p2.y - p0.y) * tension;
    const cp2x = p2.x - (p3.x - p1.x) * tension;
    const cp2y = p2.y - (p3.y - p1.y) * tension;
    d.push(`C ${cp1x},${cp1y} ${cp2x},${cp2y} ${p2.x},${p2.y}`);
  }
  return d.join(" ");
}

export function SparklineChart({
  data,
  className,
  color = "#38bdf8",
  height = 60,
  width = 200,
  showArea = false,
  animate = true,
}: SparklineChartProps) {
  const uid = useId();
  const gradientId = `sparkline-grad-${uid}`;

  const { linePath, areaPath, totalLength } = useMemo(() => {
    if (data.length < 2) return { linePath: "", areaPath: "", totalLength: 0 };

    const padding = 2;
    const min = Math.min(...data);
    const max = Math.max(...data);
    const range = max - min || 1;

    const points = data.map((v, i) => ({
      x: padding + (i / (data.length - 1)) * (width - padding * 2),
      y: padding + (1 - (v - min) / range) * (height - padding * 2),
    }));

    const line = buildSmoothPath(points);

    // Approximate path length
    let len = 0;
    for (let i = 1; i < points.length; i++) {
      const dx = points[i].x - points[i - 1].x;
      const dy = points[i].y - points[i - 1].y;
      len += Math.sqrt(dx * dx + dy * dy);
    }

    const area = `${line} L ${points[points.length - 1].x},${height} L ${points[0].x},${height} Z`;

    return { linePath: line, areaPath: area, totalLength: len };
  }, [data, width, height]);

  if (data.length < 2) return null;

  return (
    <svg
      width={width}
      height={height}
      viewBox={`0 0 ${width} ${height}`}
      fill="none"
      className={cn("overflow-visible", className)}
    >
      <defs>
        <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor={color} stopOpacity={0.3} />
          <stop offset="100%" stopColor={color} stopOpacity={0} />
        </linearGradient>
      </defs>

      {showArea && (
        <motion.path
          d={areaPath}
          fill={`url(#${gradientId})`}
          initial={animate ? { opacity: 0 } : undefined}
          animate={animate ? { opacity: 1 } : undefined}
          transition={{ duration: 1, delay: 0.6 }}
        />
      )}

      <motion.path
        d={linePath}
        stroke={color}
        strokeWidth={2}
        strokeLinecap="round"
        strokeLinejoin="round"
        fill="none"
        initial={
          animate
            ? { strokeDasharray: totalLength, strokeDashoffset: totalLength }
            : undefined
        }
        animate={animate ? { strokeDashoffset: 0 } : undefined}
        transition={
          animate
            ? { duration: 1.2, ease: "easeOut" }
            : undefined
        }
      />
    </svg>
  );
}
